    AKO STUDIOS — Embrace The Chaos  * { margin: 0; padding: 0; box-sizing: border-box; }
body {
background: #000;
overflow: hidden;
width: 100vw;
height: 100vh;
display: flex;
align-items: center;
justify-content: center;
font-family: 'Space Mono', monospace;
}

<p>/* ── STAGE ── */
#stage {
width: min(100vw, 177.78vh);
height: min(100vh, 56.25vw);
position: relative;
background: #000;
overflow: hidden;
}</p>
<p>/* ── GRAIN ── */
#stage::after {
content: &#39;&#39;;
position: absolute;
inset: 0;
background-image: url(&quot;data:image/svg+xml,%3Csvg viewBox=&#39;0 0 200 200&#39; xmlns=&#39;<a href="http://www.w3.org/2000/svg'%3E%3Cfilter">http://www.w3.org/2000/svg&#39;%3E%3Cfilter</a> id=&#39;n&#39;%3E%3CfeTurbulence type=&#39;fractalNoise&#39; baseFrequency=&#39;0.75&#39; numOctaves=&#39;4&#39; stitchTiles=&#39;stitch&#39;/%3E%3C/filter%3E%3Crect width=&#39;100%25&#39; height=&#39;100%25&#39; filter=&#39;url(%23n)&#39; opacity=&#39;0.07&#39;/%3E%3C/svg%3E&quot;);
pointer-events: none;
z-index: 200;
opacity: 0.5;
mix-blend-mode: overlay;
animation: grainShift 0.08s steps(1) infinite;
}</p>
<p>@keyframes grainShift {
0% { transform: translate(0,0); }
25% { transform: translate(-2px, 1px); }
50% { transform: translate(1px, -2px); }
75% { transform: translate(2px, 1px); }
100% { transform: translate(-1px, 2px); }
}</p>
<p>/* ── SCENE BASE ── */
.scene {
position: absolute;
inset: 0;
opacity: 0;
pointer-events: none;
}</p>
<p>.scene.active { opacity: 1; }</p>
<p>/* ── BACKGROUND LAYERS ── */
.bg {
position: absolute;
inset: 0;
display: flex;
align-items: center;
justify-content: center;
}</p>
<p>/* ============================================
SCENE 1 — BLACK. SILENCE. (0–2s)
============================================ */
#s1 { background: #000; }</p>
<p>#s1 .center-dot {
width: 4px;
height: 4px;
border-radius: 50%;
background: #fff;
animation: dotPulse 2s ease forwards;
}</p>
<p>@keyframes dotPulse {
0% { transform: scale(0); opacity: 0; }
40% { transform: scale(1); opacity: 1; }
80% { transform: scale(1); opacity: 1; }
100% { transform: scale(80); opacity: 0; }
}</p>
<p>/* ============================================
SCENE 2 — WHITE FLASH → &quot;C&quot; (2–4.5s)
============================================ */
#s2 { background: #f5f2ec; }</p>
<p>#s2 .flash {
position: absolute;
inset: 0;
background: #fff;
animation: flashOut 0.6s ease forwards;
}</p>
<p>@keyframes flashOut {
0% { opacity: 1; }
100% { opacity: 0; }
}</p>
<p>#s2 .big-c {
font-family: &#39;Bebas Neue&#39;, sans-serif;
font-size: 60vmin;
color: #000;
line-height: 1;
animation: cReveal 2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
transform-origin: center;
}</p>
<p>@keyframes cReveal {
0% { opacity: 0; transform: scale(2.5) rotate(-8deg); }
60% { opacity: 1; transform: scale(1) rotate(0deg); }
100% { opacity: 1; transform: scale(1) rotate(0deg); }
}</p>
<p>#s2 .small-tag {
position: absolute;
bottom: 8%;
right: 6%;
font-family: &#39;Space Mono&#39;, monospace;
font-size: 1.2vmin;
letter-spacing: 0.4em;
text-transform: uppercase;
color: #999;
animation: fadeInDelay 1s 1.2s ease forwards;
opacity: 0;
}</p>
<p>@keyframes fadeInDelay {
to { opacity: 1; }
}</p>
<p>/* ============================================
SCENE 3 — CHAOS TEXTURE (4.5–7s)
============================================ */
#s3 { background: #0a0a0a; }</p>
<p>#s3 .chaos-grid {
position: absolute;
inset: 0;
display: grid;
grid-template-columns: repeat(12, 1fr);
grid-template-rows: repeat(7, 1fr);
gap: 2px;
}</p>
<p>.chaos-cell {
background: #111;
animation: cellFlicker var(--dur, 0.3s) var(--del, 0s) ease infinite alternate;
}</p>
<p>@keyframes cellFlicker {
0% { background: #0a0a0a; }
50% { background: var(--c, #1a1a1a); }
100% { background: #080808; }
}</p>
<p>#s3 .chaos-text {
position: absolute;
inset: 0;
display: flex;
align-items: center;
justify-content: center;
z-index: 10;
}</p>
<p>#s3 .chaos-word {
font-family: &#39;Bebas Neue&#39;, sans-serif;
font-size: 18vmin;
color: #fff;
letter-spacing: -0.02em;
animation: chaosWord 2.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);
}</p>
<p>@keyframes chaosWord {
0% { opacity: 0; transform: translateX(-8%) skewX(-12deg); clip-path: polygon(0 0, 0 0, 0 100%, 0 100%); }
30% { opacity: 1; transform: translateX(2%) skewX(2deg); clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); }
70% { opacity: 1; transform: translateX(0) skewX(0deg); }
100% { opacity: 1; transform: translateX(0) skewX(0deg); }
}</p>
<p>/* ============================================
SCENE 4 — CCC EMBROIDERED (7–12s)
============================================ */
#s4 { background: #f0ebe2; }</p>
<p>#s4 .fabric-bg {
position: absolute;
inset: 0;
background:
repeating-linear-gradient(0deg, rgba(0,0,0,0.04) 0px, rgba(0,0,0,0.04) 1px, transparent 1px, transparent 8px),
repeating-linear-gradient(90deg, rgba(0,0,0,0.04) 0px, rgba(0,0,0,0.04) 1px, transparent 1px, transparent 8px);
}</p>
<p>#s4 .emb-container {
position: relative;
z-index: 5;
text-align: center;
}</p>
<p>#s4 .emb-ccc {
font-family: &#39;Playfair Display&#39;, serif;
font-weight: 900;
font-size: 22vmin;
color: transparent;
-webkit-text-stroke: 3px #1a1a1a;
letter-spacing: -0.05em;
line-height: 1;
animation: embStitch 4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
position: relative;
}</p>
<p>@keyframes embStitch {
0% { opacity: 0; -webkit-text-stroke-width: 0px; letter-spacing: 0.3em; }
20% { opacity: 1; -webkit-text-stroke-width: 1px; }
60% { -webkit-text-stroke-width: 3px; letter-spacing: -0.05em; }
100% { -webkit-text-stroke-width: 3px; letter-spacing: -0.05em; }
}</p>
<p>#s4 .emb-ccc::after {
content: &#39;CCC&#39;;
position: absolute;
inset: 0;
color: #1a1a1a;
-webkit-text-stroke: 0px;
animation: embFill 4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
clip-path: inset(0 100% 0 0);
}</p>
<p>@keyframes embFill {
0% { clip-path: inset(0 100% 0 0); }
100% { clip-path: inset(0 0% 0 0); }
}</p>
<p>#s4 .emb-sub {
margin-top: 2vmin;
font-family: &#39;Space Mono&#39;, monospace;
font-size: 1.4vmin;
letter-spacing: 0.8em;
text-transform: uppercase;
color: #888;
animation: fadeInDelay 1s 2s ease forwards;
opacity: 0;
}</p>
<p>#s4 .thread-line {
position: absolute;
width: 60vmin;
height: 1px;
background: linear-gradient(90deg, transparent, #aaa, transparent);
animation: threadDraw 2s 1s ease forwards;
transform: scaleX(0);
transform-origin: left;
}</p>
<p>@keyframes threadDraw {
to { transform: scaleX(1); }
}</p>
<p>/* ============================================
SCENE 5 — MANIFESTO (12–17s)
============================================ */
#s5 { background: #000; }</p>
<p>#s5 .lines-container {
display: flex;
